function b632_read(string $root, string $name): array
{
    $path = $root . '/storage/' . $name . '.json';
    $data = json_decode((string) file_get_contents($path), true);
    if (!is_array($data)) throw new RuntimeException('Invalid JSON: ' . $path);
    return $data;
}

function b632_write(string $root, string $name, array $data): void
{
    $path = $root . '/storage/' . $name . '.json';
    $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION);
    if (!is_string($json) || file_put_contents($path, $json . PHP_EOL, LOCK_EX) === false) {
        throw new RuntimeException('Unable to persist ' . $path);
    }
}

function b632_hash(mixed $value): string
{
    return hash('sha256', (string) json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
}

