function b632_unique(array $values): array
{
    $out = [];
    foreach ($values as $value) if (is_scalar($value) && (string) $value !== '') $out[(string) $value] = true;
    $result = array_keys($out); sort($result, SORT_STRING); return $result;
}

function b632_gcd(int $a, int $b): int
{
    $a=abs($a);$b=abs($b);while($b!==0){$t=$a%$b;$a=$b;$b=$t;}return max(1,$a);
}

function b632_depth(mixed $value): ?int
{
    return is_numeric($value) && (int) $value >= 1 && (int) $value <= 5 ? (int) $value : null;
}

function b632_normalize(string $text): string
{
    $text = html_entity_decode(strip_tags($text), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $text = mb_strtolower($text, 'UTF-8');
    $text = preg_replace('/[^\pL\pN]+/u', ' ', $text) ?? $text;
    return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
}

function b632_concept_map(array $concepts, array $subjects, array $domains, array $topics): array
{
    $out = [];
    foreach ($concepts as $concept) {
        $topicId = (string) ($concept['topic_id'] ?? '');
        $topic = $topics[$topicId] ?? [];
        $domainId = (string) ($topic['domain_id'] ?? $concept['domain_id'] ?? '');
        $domain = $domains[$domainId] ?? [];
        $subjectId = (string) ($domain['subject_id'] ?? $concept['subject_id'] ?? '');
        if ($subjectId === '') continue;
        $board = (string) ($subjectId === 'general-information' || $subjectId === 'verbal-ability' || $subjectId === 'analytical-logical' || $subjectId === 'numerical-ability' || $subjectId === 'clerical-ability' ? 'civil-service' : '');
        if ($board !== '') $out[(string) $concept['id']] = ['concept_id'=>(string)$concept['id'],'topic_id'=>$topicId,'domain_id'=>$domainId,'subject_id'=>$subjectId];
    }
    return $out;
}

function b632_concept_counts(array $questions, array $eligibility, array $map): array
{
    $native = []; $effective = []; $seenDirect = [];
    foreach ($questions as $q) {
        $id=(string)($q['id']??'');$tax=is_array($q['taxonomy']??null)?$q['taxonomy']:[];
        if (($tax['board_id']??$q['board']??'')==='civil-service' && isset($map[(string)($tax['concept_id']??'')])) {
            $c=(string)$tax['concept_id'];$native[$c]=($native[$c]??0)+1;
        }
    }
    foreach ($eligibility as $entry) {
        if (!is_array($entry)||!in_array('civil-service',(array)($entry['exam_ids']??[]),true)) continue;
        foreach ((array)($entry['question_ids']??[]) as $qid) {
            $qid=(string)$qid;$question=null;
            foreach ($questions as $q) if ((string)($q['id']??'')===$qid) {$question=$q;break;}
            if ($question===null) continue;
            $m=$entry['question_mappings'][$qid]??[];$placement=$m['placements']['civil-service']??[];
            $c=(string)($placement['concept_id']??$question['taxonomy']['concept_id']??'');
            if (isset($map[$c])) {$effective[$c]=($effective[$c]??0)+1;$seenDirect[$qid]=true;}
        }
    }
    return ['native'=>$native,'effective'=>$effective];
}

