/* Each item is a distinct task; repeated family labels describe skill, not stem templates. */
$specs=[];$familyCounts=[];
$push=static function(string $concept,string $stem,string $answer,array $wrong,string $why,string $family,string $misconception,int $depth=3,bool $version=false,?array $calculation=null)use(&$specs,&$familyCounts,$map):void{
    if(!isset($map[$concept]))throw new RuntimeException('Unmapped CSE concept: '.$concept);
    if(count($wrong)!==3||count(array_unique(array_merge([$answer],$wrong)))!==4)throw new RuntimeException('Invalid option set for '.$concept.' / '.$stem);
    $familyLimit=match(true){str_starts_with($family,'filing-order-task-'),str_starts_with($family,'filing-key-family-')=>1,str_starts_with($family,'record-compare-task-'),str_starts_with($family,'exact-record-key-')=>0,default=>PHP_INT_MAX};if(($familyCounts[$family]??0)>=$familyLimit)return;$familyCounts[$family]=($familyCounts[$family]??0)+1;
    if(in_array($family,['contextual-vocabulary','filipino-contextual-vocabulary'],true))$depth=min(2,$depth);
    $placement=$map[$concept];$sub=$placement['subject_id'];$area=$sub==='general-information'?'gi':($sub==='verbal-ability'?'verbal':($sub==='analytical-logical'?'analytical':($sub==='numerical-ability'?'numerical':'clerical')));
    $wave=count($specs)<205?1:(count($specs)<435?2:(count($specs)<650?3:4));
    $specs[]=['concept'=>$concept,'placement'=>$placement,'area_key'=>$area,'stem'=>$stem,'answer'=>$answer,'wrong'=>$wrong,'why'=>$why,'family'=>$family,'misconception'=>$misconception,'depth'=>$depth,'version_sensitive'=>$version,'calculation'=>$calculation,'wave'=>$wave];
};

$add=static function(array $row)use($push):void{
