};

function b632_calc_operation(string $label): ?string
{
    return match($label){
        'percent-base'=>'percent_increase','rate-time'=>'rate_times_time','ratio'=>'ratio_share_auto',
        'mean','sum-vs-mean'=>'mean','fraction-complement'=>'fraction_budget_remaining','fraction_complement'=>'fraction_remaining',
        'divide-by-rate'=>'inverse_rate','percent-change','percent_change','final-as-base','final-base'=>'percent_change',
        'percent-as-whole','percent-of-total'=>'percent_of_count','mean-total','mean-as-item'=>'missing_mean',
        'parts-not-total','smaller-part-confusion','ratio-part'=>'ratio_share_auto',
        'decimal-hours-as-minutes','decimal-time'=>'time_to_minutes','failure-to-simplify'=>'decimal_to_fraction',
        'fraction-denominator-only','fraction-operation','multiply-by-denominator'=>'fraction_of_total',
        'add-workers-and-hours','mean-divided-again'=>'multiply','mean-as-total'=>'multiply',
        'ratio-not-scaled'=>'proportional_scale','multiply-rate'=>'unit_rate','choose-lower-middle'=>'median',
        'constant-difference','difference-only','subtract-fixed-amount','increasing-even-differences','multiply-add-sequence','halving-sequence','skip-prime-or-count-odd'=>null,
        'difference'=>'difference','discount-as-total'=>'percent_discount',
        'operations-not-reversed'=>'undo_divide_then_add','difference-as-percent'=>'percent_of_total',
        'multiply-distance-time'=>'distance_time','ratio-parts-as-values'=>'ratio_share_auto',
        'decimal-place-error'=>'multiply','rate-scale'=>'rate_scale','fraction-operation'=>'fraction_of_total',
        default=>$label,
    };
}

function b632_calculate(array $calculation, string $stem=''): mixed
{
    $op=(string)($calculation['operation']??'');$x=(array)($calculation['inputs']??[]);$expected=$calculation['expected']??null;
    $n=static fn(int $i): float=>(float)($x[$i]??0);
    $fraction=static function(float $v): string { $den=100000; $num=(int)round($v*$den);$g=b632_gcd($num,$den);$num=intdiv($num,$g);$den=intdiv($den,$g);return $den===1?(string)$num:$num.'/'.$den; };
    return match($op){
        'percent_increase'=>(float)($calculation['base']??$n(0))*(1+(float)($calculation['percent']??$n(1))/100),
        'percent_of_total'=>round($n(0)/max(1,$n(1))*100,8),
        'percent_of_count'=>$n(0)*$n(1)/100,
        'percent_complement'=>100-$n(0),
        'ratio_share'=>((float)$calculation['total'])*(array_sum((array)$calculation['parts'])?((float)((array)$calculation['parts'])[(int)($calculation['requested_index']??0)])/array_sum((array)$calculation['parts']):0),
        'ratio_share_auto'=>b632_ratio_share($x,$stem),
        'ratio'=>b632_ratio_share($x,$stem),
        'ratio_largest'=>b632_ratio_share($x,'larger'),
        'ratio_reduce'=>b632_reduce_ratio($n(0),$n(1)),
        'fraction_reduce'=>b632_reduce_fraction($n(0),$n(1)),
        'fraction_to_decimal'=>round($n(0)/max(1,$n(1)),8),
        'mean'=>array_sum((array)($calculation['values']??$x))/max(1,count((array)($calculation['values']??$x))),
        'rate_times_time'=>(float)($calculation['rate']??$n(0))*(float)($calculation['time']??$n(1)),
        'rate_scale'=>count($x)>=4?$n(0)/max(1,$n(1))*$n(2):$n(0)/max(1,$n(1))*$n(2),
        'unit_rate'=>$n(0)/max(1,$n(1)),
        'rate_compare'=>b632_compare_rates($x),
        'compare_rates'=>b632_compare_rates($x),
        'compare_two_rates'=>b632_compare_two_rates($x),
        'difference'=>(float)($calculation['minuend']??$n(0))-(float)($calculation['subtrahend']??$n(1)),
        'largest_absolute_step'=>b632_largest_absolute_step($x),
        'largest_step_label'=>b632_largest_step_label($x),
        'fraction_add'=>b632_fraction_add((array)($calculation['left']??[]),(array)($calculation['right']??[])),
        'fraction_rate'=>$fraction($n(0)/max(1,$n(1))/$n(2)),
        'fraction_remaining'=>b632_fraction_subtract($n(0),$n(1),$n(2),$n(3)),
        'fraction_remaining_after_parts'=>b632_fraction_remaining_after_parts($n(0),$n(1),$n(2),$n(3)),
        'fraction_complement'=>b632_fraction_subtract(1,1,$n(0),$n(1)),
        'time_to_fill'=>$n(2)*$n(1)/max(0.0000001,$n(0)),
        'fraction_budget_remaining'=>$n(0)*(1-$n(1)/max(1,$n(2))),
        'reverse_percent'=>$n(0)/(1-$n(1)/100),
        'missing_mean'=>$n(0)*$n(1)-$n(2),
        'minutes_per_unit'=>$n(0)*60/max(1,$n(1)),
        'distance_time'=>$n(0)/max(0.0000001,$n(1)),
        'percent_change'=>abs($n(1)-$n(0))/max(1,$n(0))*100,
        'percent_discount'=>$n(0)*(1-$n(1)/100),
        'percent_then_add'=>$n(0)*(1-$n(1)/100)+$n(2),
        'part_percent_total'=>$n(0)/($n(1)/100),
        'inverse_rate'=>$n(2)/($n(0)/max(1,$n(1))),
