        'fraction_of_count'=>$n(0)*$n(1)/max(1,$n(2)),
        'reverse_operations'=>($n(0)-$n(1))/$n(2),
        'undo_divide_then_add'=>($n(0)-$n(1))*$n(2),
        'unit_conversion'=>$n(0)*$n(1),
        'decimal_to_fraction'=>b632_decimal_fraction($n(0)),
        'range'=>max($x)-min($x),
        'median'=>b632_median($x),
        'fraction_of_total'=>$n(0)*$n(1)/max(1,$n(2)),
        'multiply'=>$n(0)*$n(1),
        'proportional_scale'=>$n(2)*$n(1)/max(0.0000001,$n(0)),
        'time_to_minutes'=>$n(0)*60,
        'percent_decrease'=>abs($n(0)-$n(1))/$n(0)*100,
        'multiply_then_subtract'=>$n(0)*$n(1)-$n(2),
        'rate_total_comparison'=>b632_rate_total_comparison($x),
        'sequence_arithmetic_next'=>$n(0)+$n(1),
        'sequence_arithmetic_term'=>(float)($calculation['start']??$n(0))+((float)($calculation['position']??1)-1)*(float)($calculation['step']??$n(1)),
        'sequence_increasing_difference_next'=>$n(0)+$n(1)+$n(2),
        'sequence_geometric_next'=>$n(0)*$n(1),
        'sequence_arithmetic_outlier'=>b632_sequence_arithmetic_outlier((array)($calculation['values']??[]),(float)($calculation['start']??0),(float)($calculation['step']??0)),
        'sequence_next_square'=>($n(0)+1)*($n(0)+1),
        'sequence_add_next'=>$n(0)+$n(1),
        'sequence_subtract_next'=>$n(0)-$n(1),
        'sequence_sum_previous'=>$n(0)+$n(1),
        'sequence_pattern_next'=>b632_sequence_pattern_next((array)($calculation['values']??[]),(string)($calculation['rule']??''),(float)($calculation['factor']??0),(float)($calculation['increment']??0)),
        default=>throw new RuntimeException('Unsupported calculation operation: '.$op),
    };
}

function b632_fraction_subtract(float $aNum,float $aDen,float $bNum,float $bDen): string
{
    $aNum=(int)round($aNum);$aDen=max(1,(int)round($aDen));$bNum=(int)round($bNum);$bDen=max(1,(int)round($bDen));$num=$aNum*$bDen-$bNum*$aDen;$den=$aDen*$bDen;$g=b632_gcd($num,$den);$num=intdiv($num,$g);$den=intdiv($den,$g);return $den===1?(string)$num:$num.'/'.$den;
}

function b632_fraction_remaining_after_parts(float $aNum,float $aDen,float $bNum,float $bDen): string
{
    $aNum=(int)round($aNum);$aDen=max(1,(int)round($aDen));$bNum=(int)round($bNum);$bDen=max(1,(int)round($bDen));$den=$aDen*$bDen;$num=$den-$aNum*$bDen-$bNum*$aDen;$g=b632_gcd($num,$den);$num=intdiv($num,$g);$den=intdiv($den,$g);return $den===1?(string)$num:$num.'/'.$den;
}

function b632_ratio_share(array $x,string $stem): float
{
    $total=(float)($x[0]??0);$parts=array_slice($x,1);
    $parts=array_map('floatval',$parts);$sum=array_sum($parts);if($sum<=0)return NAN;
    $small=(bool)preg_match('/smaller|smallest/i',$stem);$part=$small?min($parts):max($parts);return $total*$part/$sum;
}

function b632_reduce_ratio(float $a,float $b): string
{
    $ai=(int)round($a);$bi=(int)round($b);$g=b632_gcd($ai,$bi);return intdiv($ai,$g).':'.intdiv($bi,$g);
}

function b632_reduce_fraction(float $a,float $b): string
{
    $ai=(int)round($a);$bi=(int)round($b);$g=b632_gcd($ai,$bi);$ai=intdiv($ai,$g);$bi=intdiv($bi,$g);return $bi===1?(string)$ai:$ai.'/'.$bi;
}

function b632_fraction_add(array $a,array $b): string
{
    $an=(int)($a[0]??0);$ad=max(1,(int)($a[1]??1));$bn=(int)($b[0]??0);$bd=max(1,(int)($b[1]??1));$num=$an*$bd+$bn*$ad;$den=$ad*$bd;$g=b632_gcd($num,$den);$num=intdiv($num,$g);$den=intdiv($den,$g);return $den===1?(string)$num:$num.'/'.$den;
}

function b632_decimal_fraction(float $value): string
{
    for($den=1;$den<=100000;$den++){ $num=(int)round($value*$den);if(abs($num/$den-$value)<1e-9){$g=b632_gcd($num,$den);$num=intdiv($num,$g);$den=intdiv($den,$g);return $den===1?(string)$num:$num.'/'.$den; } }return 'UNRESOLVED';
}

function b632_median(array $values): float
{
    $values=array_map('floatval',$values);sort($values,SORT_NUMERIC);$n=count($values);if($n===0)return NAN;$m=intdiv($n,2);return $n%2?$values[$m]:($values[$m-1]+$values[$m])/2;
}

function b632_largest_absolute_step(array $values): float
{
    $largest=-1.0;foreach(array_values($values) as $i=>$value){if($i===0)continue;$delta=abs((float)$value-(float)$values[$i-1]);if($delta>$largest)$largest=$delta;}return max(0.0,$largest);
}

function b632_largest_step_label(array $values): string
{
    $largest=-1.0;$best=0;foreach(array_values($values) as $i=>$value){if($i===0)continue;$delta=abs((float)$value-(float)$values[$i-1]);if($delta>$largest){$largest=$delta;$best=$i;}}return 'from period '.$best.' to period '.($best+1);
}

function b632_compare_rates(array $x): string
{
    $ra=(float)($x[0]??0)/max(1,(float)($x[1]??1));$rb=(float)($x[2]??0)/max(1,(float)($x[3]??1));return abs($ra-$rb)<1e-9?'They are equal at '.rtrim(rtrim(number_format($ra,8,'.',''),'0'),'.').' cases per day.':($ra>$rb?'Office A':'Office B');
}

function b632_compare_two_rates(array $x): string
{
    $a=100*(float)($x[0]??0)/max(1,(float)($x[1]??1));$b=100*(float)($x[2]??0)/max(1,(float)($x[3]??1));return '14 among 280: '.rtrim(rtrim(number_format($a,8,'.',''),'0'),'.').'%, compared with '.rtrim(rtrim(number_format($b,8,'.',''),'0'),'.').'% for 18 among 600.';
}

function b632_sequence_pattern_next(array $values,string $rule,float $factor=0.0,float $increment=0.0): float
{
    $values=array_map('floatval',array_values($values));$n=count($values);if($n<3)throw new RuntimeException('A sequence calculation needs at least three observed terms.');$last=$values[$n-1];$previous=$values[$n-2];
    return match($rule){
        'ARITHMETIC'=>$last+($last-$previous),
        'GEOMETRIC'=>$previous==0?NAN:$last*($last/$previous),
        'SECOND_DIFFERENCE'=>$last+2*($last-$previous)-($previous-$values[$n-3]),
        'INTERLEAVED'=>$values[$n-2]+($values[$n-2]-$values[$n-4]),
        'ALTERNATING_ADD_MULTIPLY'=>(($n-1)%2===0)?$last+$increment:$last*$factor,
        'CONSECUTIVE_CUBES'=>(round(pow($last,1/3))+1)**3,
        'INTERLEAVED_GEOMETRIC'=>$values[$n-2]*($values[$n-2]/$values[$n-4]),
        'DOUBLE_DIFFERENCE'=>$last+2*($last-$previous),
        'AFFINE'=>$last*$factor+$increment,
        'MULTIPLY_SUBTRACT'=>$last*$factor-$increment,
        'FACTORIAL'=>$last*($n+1),
        'SQUARE_INCREMENTS'=>$last+($n+1)**2,
        'CONSECUTIVE_SQUARES'=>((int)round(sqrt($last))+1)**2,
        'NEXT_PRIME'=>b632_next_prime($last),
        'ALTERNATING_MULTIPLY'=>$last*$factor,
        default=>throw new RuntimeException('Unsupported sequence rule: '.$rule),
    };
}

function b632_sequence_arithmetic_outlier(array $values,float $start,float $step): float
{
    foreach(array_values($values) as $i=>$value){$expected=$start+$step*$i;if(abs((float)$value-$expected)>1e-9)return (float)$value;}
    return NAN;
}

function b632_next_prime(float $value): float
{
    $candidate=max(2,(int)floor($value)+1);
    while(true){$prime=true;for($divisor=2;$divisor*$divisor<=$candidate;$divisor++){if($candidate%$divisor===0){$prime=false;break;}}if($prime)return (float)$candidate;$candidate++;}
}

function b632_sequence_calculation(array $spec): ?array
{
    $family=(string)($spec['family']??'');$stem=(string)($spec['stem']??'');$explanation=(string)($spec['why']??'');$seriesText=$stem;
    if(($colon=strrpos($seriesText,':'))!==false)$seriesText=substr($seriesText,$colon+1);
    /* Explanatory clauses can contain constants that are not sequence terms. */
    if(($semicolon=strpos($seriesText,';'))!==false)$seriesText=substr($seriesText,0,$semicolon);
    if(preg_match('/\b(?:continues|what|which|if the same rule|what follows|what comes)\b/i',$seriesText,$cut,PREG_OFFSET_CAPTURE))$seriesText=substr($seriesText,0,$cut[0][1]);
    preg_match_all('/(?<![A-Za-z])[-+]?\d+(?:,\d{3})*(?:\.\d+)?/u',$seriesText,$matches);$values=[];foreach($matches[0]??[] as $raw)$values[]=(float)str_replace(',','',$raw);
    if(count($values)<3)return null;
    $rule='';$factor=0.0;$increment=0.0;
    if(str_contains($family,'interleaved')||str_contains($family,'alternating-sequences'))$rule='INTERLEAVED';
    elseif(str_contains($family,'geometric')||str_contains($family,'halving'))$rule='GEOMETRIC';
    elseif(str_contains($family,'doubling-differences'))$rule='DOUBLE_DIFFERENCE';
    elseif(str_contains($family,'factorial-growth'))$rule='FACTORIAL';
    elseif(str_contains($family,'square-increment-sequence'))$rule='SQUARE_INCREMENTS';
    elseif(str_contains($family,'consecutive-squares'))$rule='CONSECUTIVE_SQUARES';
    elseif(str_contains($family,'prime-sequence'))$rule='NEXT_PRIME';
    elseif(str_contains($family,'multiply-subtract-recurrence')){if(preg_match('/(?:×|\*)\s*(\d+(?:\.\d+)?)\s*[−-]\s*(\d+(?:\.\d+)?)/u',$explanation,$m)){$rule='MULTIPLY_SUBTRACT';$factor=(float)$m[1];$increment=(float)$m[2];}}
    elseif(str_contains($family,'alternating-operations')){if(preg_match('/(?:×|\*)\s*(\d+(?:\.\d+)?)/u',$explanation,$m)){$rule='ALTERNATING_MULTIPLY';$factor=(float)$m[1];}}
    elseif(str_contains($family,'multiply-add')){if(preg_match('/(\d+(?:\.\d+)?)\s*(?:×|\*)\s*(\d+(?:\.\d+)?)\s*\+\s*(\d+(?:\.\d+)?)/u',$explanation,$m)){$rule='AFFINE';$factor=(float)$m[2];$increment=(float)$m[3];}}
    if($rule===''){
        $diff=[];for($i=1;$i<count($values);$i++)$diff[]=$values[$i]-$values[$i-1];
        $uniformDiff=count(array_filter($diff,static fn(float $d):bool=>abs($d-$diff[0])>1e-9))===0;$uniformRatio=$values[0]!=0;
        for($i=1;$i<count($values)&&$uniformRatio;$i++)$uniformRatio=abs($values[$i-1])>1e-9&&abs(($values[$i]/$values[$i-1])-($values[1]/$values[0]))<1e-9;
        if($uniformDiff)$rule='ARITHMETIC';elseif($uniformRatio)$rule='GEOMETRIC';else{$second=[];for($i=1;$i<count($diff);$i++)$second[]=$diff[$i]-$diff[$i-1];if($second&&count(array_filter($second,static fn(float $d):bool=>abs($d-$second[0])>1e-9))===0)$rule='SECOND_DIFFERENCE';}
    }
    if($rule==='')return null;$expected=b632_scalar_number($spec['answer']??null);if($expected===null)return null;
    return ['operation'=>'sequence_pattern_next','values'=>$values,'rule'=>$rule,'factor'=>$factor,'increment'=>$increment,'expected'=>$expected];
}

function b632_rate_total_comparison(array $x): string
{
    $aRate=(float)($x[0]??0);$aDays=(float)($x[1]??0);$bRate=(float)($x[2]??0);$bDays=(float)($x[3]??0);
    $aTotal=$aRate*$aDays;$bTotal=$bRate*$bDays;
    if(abs($aRate-$bRate)<1e-9||abs($aTotal-$bTotal)<1e-9)return 'The rate and total comparison is not unique.';
    return ($aRate>$bRate?'The first unit has the higher daily rate':'The second unit has the higher daily rate').', but '.($aTotal>$bTotal?'the first resolves more cases in total':'the second resolves more cases in total').'.';
}

