    elseif($mode===4){$den=3+($i%6)+intdiv($i,6);$a=1+($i%max(1,intdiv($den,2)));$remaining=$den-$a;$b=1+(($i+1)%$remaining);$sumNum=$a+$b;$sumDen=$den;$g=b632_gcd($sumNum,$sumDen);$sumNum=intdiv($sumNum,$g);$sumDen=intdiv($sumDen,$g);$ans=$sumNum.'/'.$sumDen;$stem="A clerk completes {$a}/{$den} of a register in the morning and {$b}/{$den} in the afternoon. What fraction is completed in total?";$wrong=[($sumNum+1).'/'.$sumDen,($a+$b).'/'.($den*2),$sumNum.'/'.($sumDen+1)];$why='The fractions have a common denominator: add the numerators, then reduce; the result is '.$ans.'.';$concept='cse-fractions-decimals';$family='fraction-addition';$mis='denominator-addition';$calc=['operation'=>'fraction_add','left'=>[$a,$den],'right'=>[$b,$den],'expected'=>$ans];}
