    $wrong=array_values(array_unique(array_map('strval',$wrong)));while(count($wrong)<3)$wrong[]=(string)($ans+count($wrong)+4);$add(['concept'=>$concept,'stem'=>$stem,'answer'=>(string)$ans,'wrong'=>array_slice($wrong,0,3),'why'=>$why,'family'=>$family,'misconception'=>$mis,'depth'=>($mode===5?2:3),'calculation'=>$calc]);
}

