/* A bounded set of short, original data briefs each supports three distinct analytical prompts. */
$dataBriefs=[
 ['permit desk cases',[18,23,21,31],'case'],['library renewals',[42,48,57,54],'renewal'],['corrections to records',[9,14,22,35],'correction'],['help-line callbacks',[60,52,49,43],'callback'],['clinic referrals',[24,28,35,47],'referral'],['permit waits (minutes median)',[38,34,29,28],'minute'],['training completions',[15,21,20,29],'completion'],['document returns',[33,27,22,18],'return'],['public inquiries',[80,88,96,112],'inquiry'],['route inspections',[11,17,16,25],'inspection'],['online submissions',[50,65,72,90],'submission'],['unresolved requests',[44,39,34,30],'request'],['audit exceptions',[6,8,12,11],'exception'],['records indexed',[120,150,165,210],'record'],['weather-related closures',[7,5,9,4],'closure'],['daily forms verified',[32,40,39,51],'form'],['appeals received',[14,18,25,23],'appeal'],['applications completed',[90,105,99,126],'application'],['phone abandonment rate',[12,10,8,9],'percent'],['service satisfaction responses',[25,31,38,45],'response'],['late documents',[17,20,19,28],'document'],['complaints logged',[26,24,19,15],'complaint'],['field visits',[5,9,14,22],'visit'],['queue clearances',[48,46,51,59],'case'],
];
$dataBriefs=array_slice($dataBriefs,0,2); // Keep two shared stimuli; repeated three-question value swaps did not add enough distinct competency value.
foreach($dataBriefs as $i=>$brief){[$label,$v,$unit]=$brief;if($unit==='percent')$unit='percentage point';$delta=[];for($j=0;$j<3;$j++)$delta[]=$v[$j+1]-$v[$j];$magnitude=array_map('abs',$delta);$largest=max($magnitude);$ix=array_search($largest,$magnitude,true);$interval='from period '.($ix+1).' to period '.($ix+2);$dwrong=[];foreach([0,1,2] as $j)if($j!==$ix)$dwrong[]='from period '.($j+1).' to period '.($j+2);$dwrong[]='the periods cannot be compared';$fam='data-brief-'.str_pad((string)($i+1),2,'0',STR_PAD_LEFT);$text='A service report records '.$label.' in four successive periods: '.implode(', ',$v).'.';
    $add(['concept'=>'cse-data-trends','stem'=>$text.' Which interval had the greatest absolute period-to-period change in the reported value?','answer'=>$interval,'wrong'=>$dwrong,'why'=>'The successive changes are '.implode(', ',$delta).'; the largest absolute change is '.($delta[$ix]>=0?'+':'').$delta[$ix].', '.$interval.'.','family'=>$fam,'misconception'=>'compare-levels-not-change','depth'=>3,'calculation'=>['operation'=>'largest_step_label','inputs'=>$v,'expected'=>$interval]]);
    $net=$v[3]-$v[0];$plural=str_ends_with($unit,'s')?'':($net===1?'':'s');$netText=($net>=0?'+':'').$net.' '.$unit.$plural;$other1=($net+$largest).' '.$unit.$plural;$other2=($net-$largest).' '.$unit.$plural;$other3=($v[3]+$v[0]).' '.$unit.$plural;
    $add(['concept'=>'analytical-data-comparison','stem'=>$text.' What is the net change from the first period to the last?','answer'=>$netText,'wrong'=>[$other1,$other2,$other3],'why'=>'Subtract the first value from the last: '.$v[3].' − '.$v[0].' = '.$net.'.','family'=>$fam,'misconception'=>'intermediate-change-as-net','depth'=>3,'calculation'=>['operation'=>'difference','minuend'=>$v[3],'subtrahend'=>$v[0],'expected'=>$net]]);
    $qual=$net>0?'The reported measure ended higher than it began.':($net<0?'The reported measure ended lower than it began.':'The reported measure ended at its starting value.');$add(['concept'=>'cse-evidence-strength','stem'=>$text.' No information is supplied about staffing, demand, or a policy change. Which conclusion is warranted?','answer'=>$qual.' The series alone does not identify a cause.','wrong'=>['A single policy caused the entire pattern.','The trend will continue at the same rate.','Every service unit had the same results.'],'why'=>'The series supports a description of the reported values, but omitted comparison and context prevent causal or universal claims.','family'=>$fam,'misconception'=>'descriptive-trend-as-cause','depth'=>4,'quantitative'=>true]);
}
