function b632_scalar_number(mixed $value): ?float
{
    if(is_int($value)||is_float($value)||is_numeric($value))return (float)$value;
    $text=trim(str_replace([',','₱','−','+'],['','','-',''],(string)$value));
    if(preg_match('/^(-?\d+)\/(\d+)$/u',$text,$m))return (float)$m[1]/max(1,(float)$m[2]);
    if(preg_match('/^(-?\d+(?:\.\d+)?)/u',$text,$m))return (float)$m[1];
    return null;
}

function b632_calculation_check(array $spec): array
{
    $calc=$spec['calculation']??null;if(!is_array($calc))return ['required'=>false,'pass'=>true,'result'=>null];
    $result=b632_calculate($calc,(string)$spec['stem']);$expected=$calc['expected']??null;
    if(($calc['operation']??'')==='largest_absolute_step'){$values=array_values((array)($calc['inputs']??[]));$steps=[];for($i=1;$i<count($values);$i++)$steps[]=abs((float)$values[$i]-(float)$values[$i-1]);$max=$steps?max($steps):null;$uniqueMax=$max!==null&&count(array_filter($steps,static fn(float $step):bool=>abs($step-$max)<1e-9))===1;$rn=b632_scalar_number($result);$en=b632_scalar_number($expected);$an=b632_scalar_number((string)$spec['answer']);$pass=$uniqueMax&&$rn!==null&&$en!==null&&$an!==null&&abs($rn-$en)<1e-7&&abs($rn-$an)<1e-7;return ['required'=>true,'pass'=>$pass,'result'=>$result,'expected'=>$expected,'unique_maximum'=>$uniqueMax];}
    if(($calc['operation']??'')==='largest_step_label'){$values=array_values((array)($calc['inputs']??[]));$steps=[];for($i=1;$i<count($values);$i++)$steps[]=abs((float)$values[$i]-(float)$values[$i-1]);$max=$steps?max($steps):null;$uniqueMax=$max!==null&&count(array_filter($steps,static fn(float $step):bool=>abs($step-$max)<1e-9))===1;$pass=$uniqueMax&&trim((string)$result)===trim((string)$expected)&&b632_normalize((string)$spec['answer'])===b632_normalize((string)$result);return ['required'=>true,'pass'=>$pass,'result'=>$result,'expected'=>$expected,'unique_maximum'=>$uniqueMax];}
    $rn=b632_scalar_number($result);$en=b632_scalar_number($expected);$answer=(string)$spec['answer'];$an=b632_scalar_number($answer);
    $pass=$rn!==null&&$en!==null?abs($rn-$en)<1e-7:(trim((string)$result)===trim((string)$expected));
    if($rn!==null&&$an!==null)$pass=$pass&&abs($rn-$an)<1e-7;
    elseif((string)$result==='Office A')$pass=$pass&&preg_match('/first office|office a/i',$answer)===1;
    elseif((string)$result==='Office B')$pass=$pass&&preg_match('/second office|office b/i',$answer)===1;
    else $pass=$pass&&b632_normalize($answer)===b632_normalize((string)$result);
    $unit=static function(string $value):string{$value=trim(preg_replace('/^\+?-?\d+(?:\.\d+)?\s*/u','',$value)??$value);return b632_normalize($value);};$answerUnit=$unit($answer);$matching=0;
    foreach(array_merge([$answer],array_map('strval',(array)$spec['wrong'])) as $option){$on=b632_scalar_number($option);if($rn!==null&&$on!==null&&abs($rn-$on)<1e-7&&($answerUnit===''||$unit((string)$option)===$answerUnit))$matching++;elseif($rn===null&&b632_normalize($option)===b632_normalize((string)$result))$matching++;}
    if($rn!==null&&$matching!==1)$pass=false;
    return ['required'=>true,'pass'=>$pass,'result'=>$result,'expected'=>$expected,'answer_matches'=>$an!==null&&$rn!==null?abs($rn-$an)<1e-7:(string)$result===(string)$expected,'matching_options'=>$matching,'operation'=>$calc['operation']??''];
}

function b632_sources_for(array $spec): array
{
    $ids=['csc-cse-ppt-scope-2026'];$area=$spec['area_key'];$concept=$spec['concept'];
    if($area==='gi'){
        if(preg_match('/personal data|personal identifiers|privacy/i',(string)($spec['stem']??'')))$ids[]='lawphil-ra10173';
        if(in_array($concept,['cse-ethical-public-service','cse-conflict-of-interest','cse-public-interest','cse-public-accountability'],true))$ids[]='republic-act-6713';
        elseif($concept==='cse-environmental-stewardship'){$ids[]='republic-act-9003';if(preg_match('/11898|extended producer responsibility|\bEPR\b/i',(string)($spec['stem']??'')))$ids[]='republic-act-11898';}
        elseif($concept==='cse-environmental-public-interest')$ids[]='republic-act-8749';
        elseif($concept==='cse-human-rights-dignity'){$ids[]='1987-philippine-constitution';$ids[]='universal-declaration-human-rights';}
        else $ids[]='1987-philippine-constitution';
    }elseif($area==='verbal'){
        $ids[]=$concept==='cse-filipino-word-usage'?'kwf-diksiyonaryo':'purdue-owl-grammar';
        if(in_array($concept,['cse-reading-comprehension','cse-paragraph-organization','cse-paragraph-cohesion','cse-contextual-inference'],true))$ids[]='openstax-reading-writing';
    }elseif($area==='analytical'){
        $ids[]=in_array($concept,['analytical-data-comparison','cse-data-interpretation','cse-data-trends','cse-evidence-strength'],true)?'openstax-introductory-statistics-2e':'open-textbook-logic-critical-thinking';
    }elseif($area==='numerical'){
        $ids[]='openstax-prealgebra-2e';if(in_array($concept,['cse-data-interpretation','cse-data-trends'],true))$ids[]='openstax-introductory-statistics-2e';
    }elseif(in_array($concept,['cse-proofreading','cse-spelling'],true))$ids[]='purdue-owl-grammar';
    return b632_unique($ids);
}

function b632_quality_sample(array $specs,int $wave): array
{
    $rows=array_values(array_filter($specs,static fn(array $s):bool=>(int)$s['wave']===$wave));$target=max(80,(int)ceil(count($rows)*0.20));$chosen=[];$groups=[];
    foreach($rows as $i=>$s){$language=preg_match('/[\x{0400}-\x{04FF}]/u',(string)$s['stem'])?'FILIPINO':'ENGLISH';$source=implode(',',b632_sources_for($s));$k=implode('|',[$s['area_key'],$s['concept'],$s['depth'],$s['version_sensitive']?'V':'S',$s['calculation']?'C':'N',$language,$source]);if(!isset($groups[$k]))$groups[$k]=[$i,$s];}
    foreach($groups as $pair){$i=$pair[0];$chosen[$i]=$rows[$i];}
    while(count($chosen)<$target){$best=null;$bestScore=-1;$bestTie='';foreach($rows as $i=>$s){if(isset($chosen[$i]))continue;$familyCount=0;$misconceptionCount=0;foreach($chosen as $picked){$familyCount+=(($picked['family']??'')===($s['family']??''))?1:0;$misconceptionCount+=(($picked['misconception']??'')===($s['misconception']??''))?1:0;}$score=(1/(1+$familyCount))+(1/(1+$misconceptionCount));$tie=hash('sha256',(string)$s['stem']);if($score>$bestScore||($score===$bestScore&&($bestTie===''||$tie<$bestTie))){$best=$i;$bestScore=$score;$bestTie=$tie;}}if($best===null)break;$chosen[$best]=$rows[$best];}
    ksort($chosen);return array_values($chosen);
}

